// SeedKodeKlasifikasi mengisi 435 baris master kode_klasifikasi (idempoten).
func SeedKodeKlasifikasi(db *gorm.DB) error {
	records := make([]model.KodeKlasifikasi, 0, len(masterKodeKlasifikasi))
	for _, item := range masterKodeKlasifikasi {
		var inaktifPtr *string
		if item.JangkaSimpanInaktif != "" {
			v := item.JangkaSimpanInaktif
			inaktifPtr = &v
		}
		var nasibPtr *string
		if item.NasibAkhir != "" {
			v := item.NasibAkhir
			nasibPtr = &v
		}
		records = append(records, model.KodeKlasifikasi{
			Kode:                item.Kode,
			Nama:                item.Nama,
			JangkaSimpanInaktif: inaktifPtr,
			NasibAkhir:          nasibPtr,
			SKKAD:               item.SKKAD,
			IsActive:            true,
		})
	}

	if err := db.Clauses(clause.OnConflict{
		Columns:   []clause.Column{{Name: "kode"}},
		DoUpdates: clause.AssignmentColumns([]string{"nama", "jangka_simpan_inaktif", "nasib_akhir", "skkad", "is_active"}),
	}).CreateInBatches(&records, 100).Error; err != nil {
		return err
	}

	log.Printf("✅ %d kode klasifikasi berhasil di-seed", len(records))
	return nil
}
